describe('Error Boundary - UI Crash Handling', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display fallback UI when a component throws an error', () => {
    // Navigate to a page with a component that will throw an error
    cy.visit('http://localhost:3000/error-trigger');

    // Verify the error boundary fallback screen is displayed
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');

    // Verify error message is shown
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');

    // Verify fallback UI contains a reset button
    cy.get('[data-testid="error-reset-button"]').should('be.visible');
  });

  it('should recover from error when reset button is clicked', () => {
    // Navigate to error page
    cy.visit('http://localhost:3000/error-trigger');

    // Verify error boundary is showing
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');

    // Click reset button to recover
    cy.get('[data-testid="error-reset-button"]').click();

    // Verify the normal UI is restored
    cy.get('[data-testid="error-boundary-fallback"]').should('not.exist');
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should display error details in development mode', () => {
    // Navigate to error page
    cy.visit('http://localhost:3000/error-trigger');

    // Verify error boundary is displayed
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');

    // Verify error details section exists (in dev mode)
    cy.get('[data-testid="error-details"]').should('exist');

    // Verify error stack trace is present
    cy.get('[data-testid="error-stack-trace"]').should('be.visible');
  });

  it('should handle multiple consecutive errors gracefully', () => {
    // Navigate to error page
    cy.visit('http://localhost:3000/error-trigger');

    // Verify first error is caught
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');

    // Reset from error
    cy.get('[data-testid="error-reset-button"]').click();
    cy.get('[data-testid="main-content"]').should('be.visible');

    // Trigger another error
    cy.get('[data-testid="trigger-error-button"]').click();

    // Verify second error is also caught
    cy.get('[data-testid="error-boundary-fallback"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');
  });

  it('should not catch errors outside of component tree', () => {
    // Navigate to normal page
    cy.visit('http://localhost:3000');

    // Verify main content is visible
    cy.get('[data-testid="main-content"]').should('be.visible');

    // Error boundary should not be shown for non-component errors
    cy.get('[data-testid="error-boundary-fallback"]').should('not.exist');
  });
});
